  "collected_information": {
    "environment_setup": {
      "python_version": "3.9+",
      "install_metagpt": [
        "pip install --upgrade metagpt",
        "pip install --upgrade git+https://github.com/geekan/MetaGPT.git",
        "git clone https://github.com/geekan/MetaGPT && cd MetaGPT && pip install --upgrade -e ."
      ],
      "config_file": "~/.metagpt/config2.yaml",
      "config_file_source_for_tests": "tests/config2.yaml"
    },
    "dependencies": {
      "requirements_txt": "core dependencies with pinned versions and some with ranges, no explicit test dependencies",
      "setup_py": {
        "python_version": ">=3.9",
        "test_extra_dependencies": [
          "pytest",
          "pytest-asyncio",
          "pytest-cov",
          "pytest-mock",
          "pytest-html",
          "pytest-xdist",
          "pytest-timeout",
          "connexion[uvicorn]",
          "azure-cognitiveservices-speech",
          "aioboto3",
          "gradio",
          "grpcio-status",
          "pylint",
          "pybrowsers"
        ]
      }
    },
    "ci_test_workflow": {
      "os": "ubuntu-latest",
      "python_version": "3.9",
      "dependency_install_script": "sh tests/scripts/run_install_deps.sh",
      "env_vars": {
        "ALLOW_OPENAI_API_CALL": "0"
      },
      "config_copy": "tests/config2.yaml to ~/.metagpt/config2.yaml",
      "test_command": "pytest tests/ --doctest-modules --cov=./metagpt/ --cov-report=xml:cov.xml --cov-report=html:htmlcov --durations=20 | tee unittest.txt",
      "coverage_and_reporting": "enabled with coverage reports and fail job on test failure or errors",
      "artifacts": "coverage reports and test logs uploaded"
    },
    "dependency_installation_script": {
      "pip_upgrade": "python -m pip install --upgrade pip",
      "package_install_with_tests": "pip install -e .[test]",
      "mermaid_cli_global_install": "npm install -g @mermaid-js/mermaid-cli",
      "playwright_install": "playwright install --with-deps"
    },
    "tests_folder_structure": {
      "content": [
        "config2.yaml",
        "conftest.py",
        "__init__.py",
        "mock/",
        "scripts/",
        "data/",
        "metagpt/"
      ],
      "test_execution_instructions": "none explicit"
    },
    "summary_conclusion": "Environment setup and test running fully covered; recommended to use 'pytest tests/test_researcher.py' for the target test file."
  },
